"""Blinded, phone-size viewer questions for the actual Cutroom export example."""
import argparse,json,random,shutil
from pathlib import Path
from engine import media

QUESTIONS=[dict(id='control',text='Người dẫn vừa bấm nút nào?',options=['Render selected (1)','Download latest edits','Add script','Chưa xác định được'],expected='Render selected (1)',modality='visual',range=[5.333,7.2]),dict(id='result',text='Sau khi chờ xuất, trạng thái nào xuất hiện?',options=['For review','Published to GitHub','Upload failed','Chưa kịp đọc'],expected='For review',modality='visual',range=[9.166,10.733]),dict(id='opened',text='File được mở cho thấy nội dung nào?',options=['Kiểm thử xuất MP4','Một website WordPress','Trang GitHub Releases','Không thấy file được mở'],expected='Kiểm thử xuất MP4',modality='visual',range=[13.566,16.033]),dict(id='word',text='Cụm tiếng Anh ngay trước “bấm vào đây nè” là gì?',options=['CTA','Chỉ tay','CPU','Chưa nghe rõ / không có audio'],expected='CTA',modality='audio',range=[6.05,7.55]),dict(id='covered',text='Caption hoặc hiệu ứng có che chi tiết cần xem không?',options=['Không','Có, ghi timecode bên dưới','Chưa kiểm tra'],expected=None,modality='judgment',range=[0,20.467])]

def main():
    p=argparse.ArgumentParser();p.add_argument('--comparison',type=Path,required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args();a.out.mkdir(parents=True,exist_ok=False);public=[]
    for i,path in enumerate(sorted(a.comparison.glob('Preview-*.mp4')),1):
        dest=a.out/f'Preview-{i}.mp4';shutil.copy2(path,dest);public.append(dict(label=f'Preview {i}',file=dest.name,sha256=media.sha(dest)))
    if len(public)!=3:raise ValueError('Use the actual three-variant matched-level comparison folder.')
    questions=[]
    for q in QUESTIONS:
        record={k:v for k,v in q.items() if k!='expected'};random.Random(q['id']).shuffle(record['options']);questions.append(record)
    media.write_json(a.out.parent/(a.out.name+'-private-key.json'),dict(expected={q['id']:q['expected'] for q in QUESTIONS},not_for_training=True,episode_scope='development example, not unseen evaluation'))
    data=json.dumps(dict(previews=public,questions=questions,episode_scope='development example; not unseen',reviewers=0),ensure_ascii=False).replace('</','<\\/')
    html='''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Cutroom · phiếu xem mù</title><style>body{font:16px system-ui;background:#f5f3e9;color:#173a2c;max-width:1100px;margin:auto;padding:24px}main{display:flex;flex-wrap:wrap;gap:24px}section{width:320px;max-width:100%;background:white;padding:12px;border-radius:12px}video{width:100%;max-width:360px}label{display:block;margin:8px 0}fieldset{border:1px solid #ccd7ca;margin:18px 0;padding:12px}input[type=text],input[type=number],textarea,select{box-sizing:border-box;width:100%;padding:10px}button{background:#173a2c;color:white;padding:12px;border:0;border-radius:7px;margin:12px 0}#result{height:300px}small{color:#566d60}</style><h1>Kiểm tra trải nghiệm người xem</h1><p>Xem mỗi bản một lượt ở1×, kích thước điện thoại. Không có tên preset. Đây là đoạn phát triển, chưa phải kiểm chứng trên tập unseen.</p><label>Người xem<input id="reviewer" type="text"></label><label><input id="heard" type="checkbox"> Tôi có audio và đã nghe trọn các bản ở1×.</label><main id="previews"></main><label>Lựa chọn cuối<select id="preference"><option value="">Chưa chọn</option><option>Preview 1</option><option>Preview 2</option><option>Preview 3</option><option>Hòa</option></select></label><label>Số đoạn giữ nguyên lần đầu · bỏ trống nếu chưa đo<input id="kept" type="number" min="0"></label><label>Tổng đoạn đã đánh giá<input id="judged" type="number" min="0"></label><label>Phút sửa thực tế · bỏ trống nếu chưa đo<input id="minutes" type="number" min="0" step="any"></label><button id="prepare">Tạo phiếu JSON</button><p>Phiếu không tự duyệt master và không tự tải xuống ổ C. Sao chép vào file feedback mới trên D.</p><textarea id="result" readonly aria-label="Phiếu JSON"></textarea><script>const data=DATA;const root=document.getElementById('previews');for(const p of data.previews){const section=document.createElement('section');section.innerHTML=`<h2>${p.label}</h2><video controls src="${p.file}"></video>`;for(const q of data.questions){const f=document.createElement('fieldset');const legend=document.createElement('legend');legend.textContent=q.text;f.append(legend);q.options.forEach((text,i)=>{const l=document.createElement('label'),input=document.createElement('input');input.type='radio';input.name=p.file+'-'+q.id;input.value=text;l.append(input,document.createTextNode(text));f.append(l)});const stamp=document.createElement('input');stamp.type='text';stamp.placeholder='Timecode / ghi chú';stamp.dataset.note=p.file+'-'+q.id;f.append(stamp);section.append(f)}root.append(section)}document.getElementById('prepare').onclick=()=>{const reviewer=document.getElementById('reviewer').value.trim();if(!reviewer){alert('Nhập người xem thực tế.');return}const listened=document.getElementById('heard').checked;const answers=data.previews.map(p=>({label:p.label,sha256:p.sha256,answers:data.questions.map(q=>({id:q.id,answer:q.modality==='audio'&&!listened?null:document.querySelector('input[name="'+p.file+'-'+q.id+'"]:checked')?.value||null,note:document.querySelector('input[data-note="'+p.file+'-'+q.id+'"]').value,modality:q.modality,status:q.modality==='audio'&&!listened?'UNVERIFIED':'REVIEWER_RESPONSE'}))}));const num=id=>document.getElementById(id).value===''?null:Number(document.getElementById(id).value);document.getElementById('result').value=JSON.stringify({reviewer,can_listen:listened,speed:1,width_px:320,episode_scope:data.episode_scope,answers,preference:document.getElementById('preference').value||null,kept_first_pass:num('kept'),judged_segments:num('judged'),human_edit_minutes:num('minutes'),release:'NEEDS_REVIEW',training_label_approved:false},null,2);document.getElementById('result').select()};</script></html>'''.replace('DATA',data)
    (a.out/'index.html').write_text(html,encoding='utf-8');media.write_json(a.out/'questions.json',dict(previews=public,questions=questions,reviewers=0,correct_answers_visible=False,first_pass_acceptance=None,correction_minutes_per_finished_minute=None));print(str((a.out/'index.html').resolve()))

if __name__=='__main__':main()
